  data = $ggnjson${"slug": "genetics-and-genomics-for-nursing", "title": "Genetics and Genomics for Nursing", "description": "This course builds the genomic vocabulary nurses need for safe, informed care: DNA and gene expression, inheritance patterns, chromosomal and single-gene disorders, family history, genetic testing, pharmacogenomics, hereditary cancer risk, ethics, patient teaching, documentation, precision health, and interprofessional workflow.", "topics": [{"id": "dad873a5-6abb-43c8-8e2b-e6753c02eb60", "type": "topic", "title": "Genomic Foundations for Nursing Practice", "description": "Build the DNA, gene expression, and genome vocabulary nurses need for safe, informed care.", "children": [{"id": "d2376dc3-1e8c-4926-997e-b8a6dd341f99", "type": "subtopic", "title": "DNA and genes", "description": "Nurses need a clear foundation for explaining genetic information in plain language.", "children": [{"id": "ced000d5-7580-4bed-b785-ef07bb011921", "type": "concept", "title": "DNA structure"}, {"id": "16cc82f4-a21b-42d7-857c-f8af2a700b1b", "type": "concept", "title": "Genes"}, {"id": "10955921-80a3-465a-a544-23e437ee0c43", "type": "concept", "title": "Chromosomes"}, {"id": "6a7b5744-5ced-4630-b9fa-17a8219750f1", "type": "concept", "title": "Genome organization"}]}, {"id": "d8cb71a8-6407-479b-ade5-b71c4f3edb6f", "type": "subtopic", "title": "Gene expression", "description": "Gene expression explains why the same genome can produce different cells and health effects.", "children": [{"id": "56383e2f-0672-4fe0-bcc9-0dffe67555c0", "type": "concept", "title": "Transcription"}, {"id": "1f353f6a-fc12-48bf-8dd3-2bdc32eb9170", "type": "concept", "title": "Translation"}, {"id": "efa9d764-dd9d-4ada-8403-a158cd54cf4c", "type": "concept", "title": "Proteins"}, {"id": "cf451104-e21b-46ea-a434-7b85e5ddf4be", "type": "concept", "title": "Regulation"}]}, {"id": "83821bd3-86bd-4efb-b7f1-5c310a99e664", "type": "subtopic", "title": "Genomic vocabulary", "description": "Shared terminology prevents confusion during education, documentation, and referral.", "children": [{"id": "57324210-1b34-401e-9914-b534ef4756df", "type": "concept", "title": "Variant"}, {"id": "28e94517-46de-4995-9b2e-3af945d29e55", "type": "concept", "title": "Mutation terminology caution"}, {"id": "30595a72-bf00-4e67-b6c6-02967224d4ca", "type": "concept", "title": "Genotype"}, {"id": "dc5c19e0-bac9-4d77-831a-4a2e149f50ff", "type": "concept", "title": "Phenotype"}]}]}, {"id": "ac83b7b6-387f-4584-8f8a-274b6d63705a", "type": "topic", "title": "Patterns of Inheritance: Mendelian and Beyond", "description": "Recognize common inheritance patterns and explain why family history matters in nursing assessment.", "children": [{"id": "ad932183-fb96-45c0-99eb-2f2c21c92ad8", "type": "subtopic", "title": "Mendelian inheritance", "description": "Classic inheritance patterns help nurses recognize risk in family histories.", "children": [{"id": "fd23402b-ac55-4ed2-af3a-c487922fbd29", "type": "concept", "title": "Autosomal dominant"}, {"id": "18f3d744-64a3-4fd9-8986-cbcf82cf2347", "type": "concept", "title": "Autosomal recessive"}, {"id": "083af782-10e1-4324-ad5f-3eae6d672d48", "type": "concept", "title": "X-linked"}, {"id": "6693de39-bf2f-4016-9860-7862e0a0abec", "type": "concept", "title": "Mitochondrial inheritance"}]}, {"id": "db512fff-eddd-43fe-9594-9fb78e617709", "type": "subtopic", "title": "Nonclassic inheritance", "description": "Some patterns do not fit simple dominant or recessive rules.", "children": [{"id": "dd69feec-033c-4ad4-9ce4-1ba458f10f5c", "type": "concept", "title": "Incomplete penetrance"}, {"id": "ca062652-aca1-4c9f-8c4e-1c9fc430dfd4", "type": "concept", "title": "Variable expressivity"}, {"id": "01197e55-145f-45e7-b18d-245b1c2e472e", "type": "concept", "title": "De novo variants"}, {"id": "5dbd2bae-ca45-40cc-8044-61630b024753", "type": "concept", "title": "Anticipation"}]}, {"id": "cae3a6fb-0b44-4214-a24c-75f563f3a0ae", "type": "subtopic", "title": "Risk communication", "description": "Inheritance patterns must be communicated carefully and without false certainty.", "children": [{"id": "579bcaf7-ab5e-41aa-a7b5-99ef49d936c1", "type": "concept", "title": "Recurrence risk"}, {"id": "70ccd7d5-4da0-4e2e-8173-b8b66937a3f4", "type": "concept", "title": "Carrier risk"}, {"id": "14e60c71-593e-43b2-a784-0f71127a6cbc", "type": "concept", "title": "Family implications"}, {"id": "c7a1a1dc-a712-4624-be09-4e683b27c443", "type": "concept", "title": "Referral triggers"}]}]}, {"id": "92f4fc5c-fa86-4593-acfd-1843f1d2364c", "type": "topic", "title": "Chromosomal Disorders", "description": "Understand chromosome number and structure changes that affect development, health, and family counseling needs.", "children": [{"id": "448e9da9-4ae6-4f26-b608-c211b158d8b5", "type": "subtopic", "title": "Chromosome number changes", "description": "Aneuploidy and related conditions are common in prenatal, pediatric, and family care contexts.", "children": [{"id": "19a354c0-e56b-442b-ba29-2d429dcf8ceb", "type": "concept", "title": "Trisomy"}, {"id": "2edc73cb-ca4d-4c1e-95c1-b7e88bb53ce2", "type": "concept", "title": "Monosomy"}, {"id": "76141a53-550a-493e-b19f-3e496b376289", "type": "concept", "title": "Nondisjunction"}, {"id": "89c756a0-b643-4708-9baf-6a7765944471", "type": "concept", "title": "Mosaicism"}]}, {"id": "50097c0a-a133-4eb7-989f-5cbc25398a76", "type": "subtopic", "title": "Structural changes", "description": "Structural chromosome changes can affect phenotype, fertility, and recurrence risk.", "children": [{"id": "abbc4205-4e72-4878-9e8b-b4b944e35cb1", "type": "concept", "title": "Deletion"}, {"id": "43bda8f7-1e5e-4cf4-8db6-b5e38baeec3b", "type": "concept", "title": "Duplication"}, {"id": "761e6b00-607b-406a-bb98-d7992be1e228", "type": "concept", "title": "Translocation"}, {"id": "451732ae-e05b-4507-b5ca-aaec122874ec", "type": "concept", "title": "Inversion"}]}, {"id": "b26e8f15-4fa3-47fc-9a0c-1d4faee43dba", "type": "subtopic", "title": "Nursing implications", "description": "Nurses support assessment, education, care coordination, and family-centered communication.", "children": [{"id": "f3b958ec-06a2-4be7-bdc0-4d0487380880", "type": "concept", "title": "Developmental concerns"}, {"id": "1b46238f-5bad-4c9c-88bf-23eb20543771", "type": "concept", "title": "Screening follow-up"}, {"id": "82614504-0433-4da6-a91b-acc5fa7bfef4", "type": "concept", "title": "Family support"}, {"id": "4322b32d-6312-449d-a002-0c0bf351ec24", "type": "concept", "title": "Specialty referral"}]}]}, {"id": "0dd66a8f-e06c-497a-9591-d48517f71262", "type": "topic", "title": "Single-Gene Disorders", "description": "Connect variants in single genes to clinical presentation, screening, education, and referral needs.", "children": [{"id": "93bf147b-7aaf-468b-b3b8-a9bf618bec31", "type": "subtopic", "title": "Disease mechanisms", "description": "Single-gene disorders show how one gene can strongly shape health outcomes.", "children": [{"id": "5488b76e-8872-42e0-b361-8356fa155fe5", "type": "concept", "title": "Loss of function"}, {"id": "e34d39d3-971d-4b25-a173-348918ad5c43", "type": "concept", "title": "Gain of function"}, {"id": "0d4c669d-6d13-451e-a509-b16c4117e7d0", "type": "concept", "title": "Enzyme defects"}, {"id": "cc33c915-82b8-41e1-95cd-bd463587967a", "type": "concept", "title": "Structural protein disorders"}]}, {"id": "ef0421e8-b6bd-47e9-89ff-86e105d36cbf", "type": "subtopic", "title": "Clinical examples", "description": "Examples make inheritance and nursing implications concrete.", "children": [{"id": "33730ca9-3490-48b4-a7cf-204115c44383", "type": "concept", "title": "Cystic fibrosis"}, {"id": "a93c9572-b1ee-47c8-b489-5f0ca335c238", "type": "concept", "title": "Sickle cell disease"}, {"id": "aaf3a992-7777-40c8-b053-1177ab93fcf4", "type": "concept", "title": "Huntington disease"}, {"id": "1be06faa-be6f-419e-b6e0-bbd397c6a5af", "type": "concept", "title": "Marfan syndrome"}]}, {"id": "22f33aa8-0212-4fdf-9448-a58eae774e99", "type": "subtopic", "title": "Nursing care implications", "description": "Nurses help patients manage information, symptoms, testing, and family communication.", "children": [{"id": "9e9cabb9-9e85-4c99-b764-8e3f3074c315", "type": "concept", "title": "Carrier testing"}, {"id": "8a916c4e-ae05-434e-a1d2-3bede2f4f0c7", "type": "concept", "title": "Symptom monitoring"}, {"id": "f6ac4626-6045-455a-bd56-bd5856ee3ce0", "type": "concept", "title": "Patient education"}, {"id": "3bc193d9-a4d1-419a-9950-8348c9049a8a", "type": "concept", "title": "Referral and follow-up"}]}]}, {"id": "8e29e1e2-f30a-48c8-883d-d2933da64e78", "type": "topic", "title": "Multifactorial and Complex Inheritance", "description": "Explain how genes, environment, behavior, and social context combine in common health conditions.", "children": [{"id": "aab485a5-8c01-4bf2-ba94-7918654d988b", "type": "subtopic", "title": "Complex traits", "description": "Most common conditions reflect many genes plus environment and behavior.", "children": [{"id": "033d0d1e-f7e1-4f3b-96a4-0bd49643efaa", "type": "concept", "title": "Polygenic risk"}, {"id": "fe5a4c89-8f5b-480c-9daa-6fd86f1376d0", "type": "concept", "title": "Threshold traits"}, {"id": "41d82c38-9d07-423f-8523-79964007e3ca", "type": "concept", "title": "Gene-environment interaction"}, {"id": "39e621b1-b7fa-417a-9702-f537c773ec0e", "type": "concept", "title": "Family clustering"}]}, {"id": "d42516eb-1471-4b59-aa08-334c0e777dd3", "type": "subtopic", "title": "Common conditions", "description": "Complex inheritance connects genomics to everyday nursing care.", "children": [{"id": "14884dcf-ac14-44bd-a483-7ad8e241e3c0", "type": "concept", "title": "Diabetes"}, {"id": "267f5108-8bf2-41f7-ba10-06790b9423f9", "type": "concept", "title": "Hypertension"}, {"id": "83681833-36b4-4fdd-81ca-9a1c9a415518", "type": "concept", "title": "Asthma"}, {"id": "d754cedf-cd3d-49a6-869c-82a1ef8bb986", "type": "concept", "title": "Cardiovascular disease"}]}, {"id": "100d6112-96ad-474b-bd9c-9b9b03b04c5e", "type": "subtopic", "title": "Prevention and counseling", "description": "Complex risk should support prevention without genetic determinism.", "children": [{"id": "d259b785-44ca-47c6-950c-a12737bc1b2e", "type": "concept", "title": "Lifestyle risk reduction"}, {"id": "ecba474b-00b9-433a-b500-dec6bb0ac8db", "type": "concept", "title": "Screening"}, {"id": "94e10829-3aa1-4cc2-bde4-1356edb1679f", "type": "concept", "title": "Social determinants"}, {"id": "ff00725f-911c-4473-b656-00009085cd2a", "type": "concept", "title": "Avoiding blame"}]}]}, {"id": "393bc500-3c86-478d-9c6c-14f51d6b029c", "type": "topic", "title": "Family Health History and Pedigree Analysis", "description": "Collect and interpret family health history to identify risk patterns and guide next nursing steps.", "children": [{"id": "160efe71-7869-4651-b8fd-35aac9ce5678", "type": "subtopic", "title": "Family history collection", "description": "Family history is a low-cost genomic screening tool nurses can use across settings.", "children": [{"id": "694d1a7d-2a51-44b3-820a-a2c8262b4a90", "type": "concept", "title": "Three-generation history"}, {"id": "b8832803-e2f4-494f-9fc8-f00a7052bf7b", "type": "concept", "title": "Age of onset"}, {"id": "18d9fbb4-c3a1-4295-92d5-5a5119047c52", "type": "concept", "title": "Ethnicity and ancestry context"}, {"id": "35d7078c-a30f-4ec0-9a0a-f7c6dadf00b0", "type": "concept", "title": "Cause of death"}]}, {"id": "1d5e4d70-d438-4515-8235-49f6f35af307", "type": "subtopic", "title": "Pedigree interpretation", "description": "Pedigrees reveal patterns that may not be obvious in narrative notes.", "children": [{"id": "6ad6d179-d682-4771-8e46-f689c425ddff", "type": "concept", "title": "Symbols"}, {"id": "af0da01b-2cb2-4583-a01c-7d1036395a8a", "type": "concept", "title": "Affected relatives"}, {"id": "5d0fa4f0-563b-45f7-972b-4287b3e00817", "type": "concept", "title": "Lineage patterns"}, {"id": "96d8d6c9-9c86-4839-a605-96feecc49512", "type": "concept", "title": "Consanguinity"}]}, {"id": "385ab6aa-c9c8-46ce-974c-3d5dce9fea10", "type": "subtopic", "title": "Risk flags", "description": "Red flags help nurses know when to escalate or refer.", "children": [{"id": "c474ae69-4944-4321-bb2f-629912b921c4", "type": "concept", "title": "Early onset"}, {"id": "418ee51d-dce6-4efd-adac-0cb0ecfe1576", "type": "concept", "title": "Multiple affected relatives"}, {"id": "71690514-c457-4929-889f-d2e7f1a046ea", "type": "concept", "title": "Rare cancers"}, {"id": "86db8e5c-6543-4443-bc9c-a57ababd23ab", "type": "concept", "title": "Bilateral or multifocal disease"}]}]}, {"id": "a57f5318-c7f6-4013-afdf-dda9260c9c6b", "type": "topic", "title": "Genetic Testing, Screening, and Results Literacy", "description": "Understand types of genetic tests, possible results, limitations, and patient-facing explanations.", "children": [{"id": "84c5ef5c-2aef-4555-b90c-9f3ed8b5f682", "type": "subtopic", "title": "Testing types", "description": "Different tests answer different clinical questions and have different limits.", "children": [{"id": "083c4ad9-0057-4fbb-a442-7aa095a5193e", "type": "concept", "title": "Diagnostic testing"}, {"id": "21460371-5f66-4432-9634-e769a8006597", "type": "concept", "title": "Carrier screening"}, {"id": "1c80832a-5210-4fa7-b553-ddeaf50e0bc9", "type": "concept", "title": "Predictive testing"}, {"id": "ad751eb2-a257-465d-99db-06adcd977a07", "type": "concept", "title": "Newborn screening"}]}, {"id": "f5092dcd-4940-4706-9cbc-8ef339eeb2d5", "type": "subtopic", "title": "Result categories", "description": "Students need to understand what results can and cannot say.", "children": [{"id": "74cafcbb-5fec-47f5-8611-b70f9007896d", "type": "concept", "title": "Pathogenic variant"}, {"id": "f9827719-1245-41dc-9379-3a960ca2173d", "type": "concept", "title": "Likely pathogenic"}, {"id": "5ed029a3-1e2c-45a8-a985-f3ee443b4f31", "type": "concept", "title": "Variant of uncertain significance"}, {"id": "22c9dd4b-3076-44f1-93e2-262b4633e96c", "type": "concept", "title": "Negative result limitations"}]}, {"id": "da676df7-b1db-4b14-985e-cdfb5ea1d8f4", "type": "subtopic", "title": "Pre- and post-test considerations", "description": "Testing requires informed preparation, follow-up, and psychosocial awareness.", "children": [{"id": "71b1d7f2-3230-423b-b036-1c29d32eff9e", "type": "concept", "title": "Informed consent"}, {"id": "813ccbb8-e8b4-4d2c-aff6-5467e0ba99e1", "type": "concept", "title": "Test limitations"}, {"id": "b6252a9f-7960-4d26-8991-78ea5a5f0c54", "type": "concept", "title": "Incidental findings"}, {"id": "2683f759-394d-42f5-8528-01d9b0a87961", "type": "concept", "title": "Family implications"}]}]}, {"id": "82fd3687-ce9c-4cfa-a71f-4648d5623c29", "type": "topic", "title": "Pharmacogenomics and Medication Safety", "description": "Apply genomic variation to medication response, adverse effects, and safe medication education.", "children": [{"id": "01cc344f-20ff-4f94-9119-05911fb86695", "type": "subtopic", "title": "Medication response", "description": "Genomic variation can affect drug metabolism, effectiveness, and adverse reactions.", "children": [{"id": "a82519dd-a150-476e-a060-7ed5cee5eb77", "type": "concept", "title": "Pharmacokinetics"}, {"id": "f93b8416-7d8d-46f8-9251-e42017e255ae", "type": "concept", "title": "Pharmacodynamics"}, {"id": "422f8a3b-6409-4a07-9804-7b136dbc80f0", "type": "concept", "title": "Metabolizer status"}, {"id": "53ebdc87-3e38-4c06-abe0-8d90943fa672", "type": "concept", "title": "Therapeutic response"}]}, {"id": "e88d72af-608c-44ea-a513-f9c25445a8d1", "type": "subtopic", "title": "Clinical examples", "description": "Examples help students connect genomic information to medication safety.", "children": [{"id": "bbf49a2c-b11c-41e1-8437-d111a8415667", "type": "concept", "title": "CYP2C19 and clopidogrel"}, {"id": "a5db3f19-e272-4538-a2b9-62bdac8e2220", "type": "concept", "title": "CYP2D6 and opioids"}, {"id": "fc0207e8-aed4-424b-b8b8-0a74371135ee", "type": "concept", "title": "HLA variants"}, {"id